581:       private:
582:         Tag tag_;                       // Tag identifying the field
583:         Type type_;                     // Type of the field
584:         uint32_t count_;                // Number of values
585:         std::vector<std::byte> values_; // Pointer to the value data
586:       };
587: 
588:       const std::map<Tag, Entry>& entries() const { return entries_; }
589: 
590:       const Entry& getEntry(Tag tag,
591:         std::string errorMessage = "Entry not found") const {
592:         auto it = entries_.find(tag);
593:         if (it == entries_.end()) {
594:           throw std::runtime_error(errorMessage);
595:         }
596:         return it->second;
597:       }
598: 
599:       static IFD read(std::istream& stream, bool mustSwap = false) {
600:         IFD ifd;
601: 
602:         // Read the number of entries
603:         uint16_t entryCount = readValue<uint16_t>(stream, mustSwap);
604: 
605:         // Read each entry
606:         Tag lastTag = Tag::Null;
607:         for (uint16_t i = 0; i < entryCount; ++i) {
608:           Entry entry = Entry::read(stream, mustSwap);
609:           ifd.entries_[entry.tag()] = std::move(entry);
610:           if (entry.tag() <= lastTag) {
611:             throw std::runtime_error("Entries must be sorted by tag in ascending order");
612:           }
613:           lastTag = entry.tag();
614:         }
615: 
616:         return ifd;
617:       }
