490:   // TiffExporter implementation for Grayscale images ------------------------
491:   template <typename DstType, typename SrcType = DstType>
492:   class TiffExporterGray : public TiffExporter
493:   {
494:   public:
495:     // Callback for TiffCraft::load() function
496:     void operator()(
497:       const TiffImage::Header& header,
498:       const TiffImage::IFD& ifd,
499:       TiffImage::ImageData imageData) override
500:     {
501:       const int samplesPerPixel = requireSamplesPerPixel(ifd, 1);
502:       const int photometricInterpretation = requirePhotometricInterpretation(ifd, 1, std::less_equal<>());
503:       const int compression = requireCompression(ifd, 1);
504:       const int fillOrder = requireFillOrder(ifd, 1);
505: 
506:       const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
507: 
508:       constexpr size_t maxDstValue = std::numeric_limits<DstType>::max();
509:       const size_t maxSrcValue = bitsPerSample < sizeof(size_t) * 8
510:         ? (size_t(1) << bitsPerSample) - 1 : std::numeric_limits<size_t>::max();
511: 
512:       const auto rectInfo = getRectInfo(ifd);
513: 
514:       // create the image and copy the pixel data
515:       image_ = Image::make<DstType, 1>(getWidth(ifd), getHeight(ifd));
516:       using UnaryOp = std::function<DstType(DstType)>;
517:       copyRectangles<SrcType,DstType,UnaryOp>(
518:         imageData, // source pixel data
519:         rectInfo,  // rectangle info
520:         1, // source image channels
521:         1, // source image planes
522:         header.equalsHostByteOrder(), // source data byte order
523:         [&](DstType value) -> DstType {
524:           return (value * maxDstValue) / maxSrcValue;
525:         }
526:       );
527: 
528:       if (photometricInterpretation == 0) { // WhiteIsZero
529:         invertColors();
530:       }
531:     }
532:   };
