534:   // TiffExporter implementation for Palette-color images --------------------
535:   template <typename DstType, typename SrcType = DstType>
536:   class TiffExporterPalette : public TiffExporter
537:   {
538:   public:
539:     // Callback for TiffCraft::load() function
540:     void operator()(
541:       const TiffImage::Header& header,
542:       const TiffImage::IFD& ifd,
543:       TiffImage::ImageData imageData) override
544:     {
545:       const int samplesPerPixel = requireSamplesPerPixel(ifd, 1);
546:       const int photometricInterpretation = requirePhotometricInterpretation(ifd, 3);
547:       const int compression = requireCompression(ifd, 1);
548:       const int fillOrder = requireFillOrder(ifd, 1);
549: 
550:       const int bitsPerSample = getInt(ifd, Tag::BitsPerSample, 1);
551: 
552:       const auto numColors = (1 << bitsPerSample);
553:       const auto colorMap = getIntVec(ifd, Tag::ColorMap);
554:       if (3 * numColors > colorMap.size()) {
555:         throw std::runtime_error("Color map size does not match bits per sample");
556:       }
557:       const int chan[3] = { numColors * 0, numColors * 1, numColors * 2 };
558: 
559:       constexpr int bitsPerDstPixel = 8 * sizeof(DstType);
560: 
561:       const auto rectInfo = getRectInfo(ifd);
562: 
563:       // create the image and copy the pixel data
564:       image_ = Image::make<DstType, 3>(getWidth(ifd), getHeight(ifd));
565:       using UnaryOp = std::function<Rgb<DstType>(DstType)>;
566:       copyRectangles<SrcType,DstType,UnaryOp>(
567:         imageData, // source pixel data
568:         rectInfo,  // rectangle info
569:         1, // source image channels
570:         1, // source image planes
571:         header.equalsHostByteOrder(), // source data byte order
572:         [&](DstType value) -> Rgb<DstType> {
573:           return {
574:             static_cast<DstType>(colorMap[chan[0] + value] >> (16 - bitsPerDstPixel)),
575:             static_cast<DstType>(colorMap[chan[1] + value] >> (16 - bitsPerDstPixel)),
576:             static_cast<DstType>(colorMap[chan[2] + value] >> (16 - bitsPerDstPixel))
577:           };
578:         }
579:       );
580:     }
581:   };
