123: std::ostream& operator<<(std::ostream& os, const TiffCraft::TiffImage::IFD::Entry& entry) {
124:   using namespace TiffCraft;
125:   os << "Tag: " << entry.tag() << "; "
126:      << "Type: " << entry.type() << "; "
127:      << "Count: " << entry.count() << ": "
128:      << "Value:";
129:   if (entry.type() == Type::ASCII) {
130:     // For ASCII type, print as a string
131:     os << " " << std::string(reinterpret_cast<const char*>(entry.values()), entry.bytes() - 1);
132:   } else {
133:     for (int i = 0; i < entry.count(); ++i) {
134:       const std::byte* value = entry.values() + i * TiffCraft::typeBytes(entry.type());
135:       switch (entry.type()) {
136:         case Type::BYTE:
137:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::BYTE>*>(value);
138:           break;
139:         case Type::SHORT:
140:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SHORT>*>(value);
141:           break;
142:         case Type::LONG:
143:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::LONG>*>(value);
144:           break;
145:         case Type::RATIONAL: {
146:           const auto* rational = reinterpret_cast<const TypeTraits_t<Type::RATIONAL>*>(value);
147:           os << " " << rational->numerator << "/" << rational->denominator;
148:           break;
149:         }
150:         case Type::SBYTE:
151:           os << " " << static_cast<int>(*reinterpret_cast<const TypeTraits_t<Type::SBYTE>*>(value));
152:           break;
153:         case Type::UNDEFINED: {
154:           const auto* undefined = reinterpret_cast<const TypeTraits_t<Type::UNDEFINED>*>(value);
155:           os << " 0x" << std::hex << std::setw(2) << std::setfill('0')
156:              << static_cast<int>(*undefined) << std::dec << std::setw(1) <<std::setfill(' ');
157:           break;
158:         }
159:         case Type::SSHORT:
160:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SSHORT>*>(value);
161:           break;
162:         case Type::SLONG:
163:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SLONG>*>(value);
164:           break;
165:         case Type::SRATIONAL: {
166:           const auto* rational = reinterpret_cast<const TypeTraits_t<Type::SRATIONAL>*>(value);
167:           os << " " << rational->numerator << "/" << rational->denominator;
168:           break;
169:         }
170:         case Type::FLOAT:
171:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::FLOAT>*>(value);
172:           break;
173:         case Type::DOUBLE:
174:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::DOUBLE>*>(value);
175:           break;
176:         default:
177:           os << " <Unsupported Type>";
178:       }
179:       if (i > 5) {
180:         // if there are more than 5 values, skip the rest
181:         os << " ...";
182:         break;
183:       }
184:     }
185:   }
