52: template <typename PixelType>
53: void compareToReference(
54:   const Image& image,
55:   const std::filesystem::path& refFilePath,
56:   int margin = 0)
57: {
58:   auto refImg = netpbm::read<PixelType>(refFilePath.string());
59:   const int channels = netpbm::is_rgb_v<PixelType> ? 3 : 1;
60:   const int bitDepth = 8 * sizeof(PixelType) / channels;
61:   REQUIRE (image.width == refImg.width);
62:   REQUIRE (image.height == refImg.height);
63:   REQUIRE (image.channels == channels);
64:   REQUIRE (image.bitDepth == bitDepth);
65:   REQUIRE (image.dataSize() == channels * refImg.width * refImg.height * (bitDepth / 8));
66:   REQUIRE (image.dataSize<PixelType>() == refImg.pixels.size());
67:   REQUIRE (image.dataPtr() != nullptr);
68:   if constexpr (netpbm::is_rgb_v<PixelType>) {
69:     using T = typename PixelType::value_type;
70:     const auto* pixels = image.dataPtr<T>();
71:     const auto* refPixels = refImg.pixels.data();
72:     for (size_t h = 0; h < image.height; ++h) {
73:       const auto* row = pixels + h * image.rowStride / sizeof(T);
74:       const auto* refRow = refPixels + h * refImg.width;
75:       for (size_t col = 0; col < image.width; ++col) {
76:         const auto* pixel = row + col * image.colStride / sizeof(T);
77:         const auto red = pixel[0 * image.chanStride / sizeof(T)];
78:         const auto green = pixel[1 * image.chanStride / sizeof(T)];
79:         const auto blue = pixel[2 * image.chanStride / sizeof(T)];
80:         REQUIRE (std::abs(double(refRow[col].r) - red) <= margin);
81:         REQUIRE (std::abs(double(refRow[col].g) - green) <= margin);
82:         REQUIRE (std::abs(double(refRow[col].b) - blue) <= margin);
83:       }
84:     }
85:   } else if constexpr (std::is_same_v<PixelType, bool>) {
86:     const uint8_t* pixels = image.dataPtr<uint8_t>();
87:     for (size_t h = 0; h < image.height; ++h) {
88:       const uint8_t* row = pixels + h * image.rowStride / sizeof(uint8_t);
89:       for (size_t col = 0; col < image.width; ++col) {
90:         const uint8_t* pixel = row + col * image.colStride / sizeof(uint8_t);
91:         const int refPixel = refImg.pixels[h * refImg.width + col] ? 0x00 : 0xff; // false = white, true = black
92:         REQUIRE (refPixel == *pixel);
93:       }
94:     }
95:   } else {
96:     using T = PixelType;
97:     const auto* pixels = image.dataPtr<T>();
98:     const auto* refPixels = refImg.pixels.data();
99:     for (size_t h = 0; h < image.height; ++h) {
100:       const auto* row = pixels + h * image.rowStride / sizeof(T);
101:       const auto* refRow = refPixels + h * refImg.width;
102:       for (size_t col = 0; col < image.width; ++col) {
103:         const auto* pixel = row + col * image.colStride / sizeof(T);
104:         REQUIRE (std::abs(double(refRow[col]) - pixel[0]) <= margin);
105:       }
106:     }
107:   }
108: }
