27: // netpbm.hpp
28: // ==========
29: // This file contains functions to load NetPBM images (PBM, PGM, PPM).
30: //
31: 
32: #include <fstream>
33: #include <vector>
34: #include <string>
35: #include <stdexcept>
36: #include <sstream>
37: #include <cstdint>
38: #include <numeric>
39: #include <type_traits>
40: 
41: namespace netpbm {
42: 
43:   template<typename T>
44:   struct RGB {
45:     T r, g, b;
46:     using value_type = T;
47:     T& operator[](size_t index) {
48:       return reinterpret_cast<T*>(&r)[index];
49:     }
50:   };
51:   using RGB8 = RGB<uint8_t>;
52:   using RGB16 = RGB<uint16_t>;
53:   using RGB32 = RGB<uint32_t>;
54: 
55:   template <typename T>
56:   struct Image {
57:       int width;
58:       int height;
59:       size_t maxval;
60:       std::vector<T> pixels;
61:   };
62: 
63:   using Image8 = Image<uint8_t>;
64:   using Image16 = Image<uint16_t>;
65:   using Image32 = Image<uint32_t>;
66: 
67:   using ImageRgb8 = Image<RGB8>;
68:   using ImageRgb16 = Image<RGB16>;
69:   using ImageRgb32 = Image<RGB32>;
70: 
71:   template <typename>
72:   struct is_rgb : std::false_type {};
73: 
74:   template <typename T>
75:   struct is_rgb<RGB<T>> : std::true_type {};
76: 
77:   template <typename T>
78:   inline constexpr bool is_rgb_v = is_rgb<T>::value;
79: 
80:   template <typename PixelType>
81:   Image<PixelType> read(const std::string& filename) {
82:     std::ifstream file(filename);
83:     if (!file) throw std::runtime_error("Cannot open file");
84: 
85:     std::string line;
86: 
87:     // Read magic number
88:     std::getline(file, line);
89:     if constexpr (std::is_same_v<PixelType, bool>) {
90:       if (line != "P1") throw std::runtime_error("Not an ASCII PBM (P1)");
91:     } else if constexpr (is_rgb_v<PixelType>) {
92:       if (line != "P3") throw std::runtime_error("Not an ASCII PPM (P3)");
93:     } else {
94:       if (line != "P2") throw std::runtime_error("Not an ASCII PGM (P2)");
95:     }
96: 
97:     // Skip comments
98:     do {
99:         std::getline(file, line);
100:     } while (line[0] == '#');
101: 
102:     // Read width and height
103:     std::istringstream wh(line);
104:     int width, height;
105:     wh >> width >> height;
106: 
107:     // Read max value
108:     size_t maxval = 1;
109:     if constexpr (!std::is_same_v<PixelType, bool>) {
110:       file >> maxval;
111:     }
112:     size_t maxValue;
113:     if constexpr (is_rgb_v<PixelType>) {
114:       maxValue = std::numeric_limits<typename PixelType::value_type>::max();
115:     }
116:     else {
117:       maxValue = std::numeric_limits<PixelType>::max();
118:     }
119:     if (maxval != maxValue) {
120:       throw std::runtime_error("Unsupported maxval");
121:     }
122: 
123:     // Read pixel data
124:     std::vector<PixelType> pixels;
125:     pixels.reserve(width * height);
126:     if constexpr (is_rgb_v<PixelType>) {
127:       unsigned long int r, g, b;
128:       while (file >> r >> g >> b) {
129:         pixels.push_back(PixelType{
130:           static_cast<typename PixelType::value_type>(r),
131:           static_cast<typename PixelType::value_type>(g),
132:           static_cast<typename PixelType::value_type>(b)});
133:       }
134:     } else {
135:       unsigned long int gray;
136:       while (file >> gray) {
137:           pixels.push_back(static_cast<PixelType>(gray));
138:       }
139:     }
140:     if (pixels.size() != static_cast<size_t>(width * height))
141:         throw std::runtime_error("Pixel count does not match image size");
142: 
143:     return {width, height, maxval, std::move(pixels)};
144:   }
145: 
146:   template <typename T>
147:   Image<RGB<T>> readPPM(const std::string& filename) {
148:     return read<RGB<T>>(filename);
149:   }
150: 
151:   template <typename T>
152:   Image<T> readPGM(const std::string& filename) {
153:     return read<T>(filename);
154:   }
155: 
156:   inline Image<bool> readPBM(const std::string& filename) {
157:     return read<bool>(filename);
158:   }
159: 
160:   template <typename PixelType>
161:   void write(const std::string& filename, const Image<PixelType>& image) {
162:     std::ofstream file(filename);
163:     if (!file) throw std::runtime_error("Cannot open file");
164: 
165:     // Write magic number
166:     if constexpr (std::is_same_v<PixelType, bool>) {
167:       file << "P1\n";
168:     } else if constexpr (is_rgb_v<PixelType>) {
169:       file << "P3\n";
170:     } else {
171:       file << "P2\n";
172:     }
173: 
174:     // Write image dimensions
175:     file << image.width << " " << image.height << "\n";
176: 
177:     // Write max value
178:     file << image.maxval << "\n";
179: 
180:     // Write pixel data
181:     for (const auto& pixel : image.pixels) {
182:       if constexpr (is_rgb_v<PixelType>) {
183:         file << static_cast<unsigned long int>(pixel.r) << " "
184:              << static_cast<unsigned long int>(pixel.g) << " "
185:              << static_cast<unsigned long int>(pixel.b) << "\n";
186:       } else {
187:         file << static_cast<unsigned long int>(pixel) << "\n";
188:       }
189:     }
190:   }
191: 
192:   template <typename T>
193:   void writePPM(const std::string& filename, const Image<RGB<T>>& image) {
194:     write<RGB<T>>(filename, image);
195:   }
196: 
197:   template <typename T>
198:   void writePGM(const std::string& filename, const Image<T>& image) {
199:     write<T>(filename, image);
200:   }
201: 
202:   inline void writePBM(const std::string& filename, const Image<bool>& image) {
203:     write<bool>(filename, image);
204:   }
205: 
206: } // namespace netpbm

