#include <tiffcraft/TiffCraft.hpp>
#include <tiffcraft/TiffStdOut.hpp>
#include <iostream>
#include <sstream>
#include <cstring>
using namespace TiffCraft;

// Build a minimal TIFF in memory: header + IFD with one ASCII entry of count 0
static std::string buildAsciiZeroCount() {
  std::string s;
  auto u16 = [&](uint16_t v){ s.append((char*)&v, 2); };
  auto u32 = [&](uint32_t v){ s.append((char*)&v, 4); };
  u16(0x4949); u16(42); u32(8);          // header, first IFD at 8
  u16(1);                                  // 1 entry
  u16(0x010E); u16(2); u32(0);            // tag=ImageDescription, type=ASCII, count=0
  u32(0);                                  // value (unused, count=0)
  u32(0);                                  // next IFD offset = 0
  return s;
}

int main() {
  // --- 1. ASCII entry with count == 0 ---
  {
    std::string data = buildAsciiZeroCount();
    std::istringstream in(data, std::ios::binary);
    try {
      auto ifd = TiffImage::IFD::read(in, false);
      std::cout << "[1] ASCII count=0: no throw, entries=" << ifd.entries().size() << "\n";
    } catch (const std::exception& e) {
      std::cout << "[1] ASCII count=0: threw: " << e.what() << "\n";
    }
  }

  // --- 2. Cyclic IFD offset (IFD points to itself) ---
  {
    std::string s;
    auto u16 = [&](uint16_t v){ s.append((char*)&v, 2); };
    auto u32 = [&](uint32_t v){ s.append((char*)&v, 4); };
    u16(0x4949); u16(42); u32(8);
    u16(0);                 // 0 entries
    u32(8);                 // next IFD offset -> points back to itself (cycle)
    std::istringstream in(s, std::ios::binary);
    try {
      auto img = TiffImage::read(in);
      std::cout << "[2] cyclic IFD: no hang, ifds=" << img.ifds().size() << "\n";
    } catch (const std::exception& e) {
      std::cout << "[2] cyclic IFD: threw: " << e.what() << "\n";
    }
  }

  // --- 3. takeImage(): move or copy? ---
  {
    TiffExporterAny ex;
    const void* before = ex.image().data.data();
    Image img = ex.takeImage();
    const void* after = ex.image().data.data();
    std::cout << "[3] takeImage(): before=" << before << " after=" << after
              << " (same buffer => copied, different => moved)\n";
  }

  // --- 4. Rational with zero denominator ---
  {
    auto e = TiffImage::IFD::Entry::read;
    // craft an entry: tag=XResolution, type=RATIONAL, count=1, numerator=1, denominator=0
    std::string s;
    auto u16 = [&](uint16_t v){ s.append((char*)&v, 2); };
    auto u32 = [&](uint32_t v){ s.append((char*)&v, 4); };
    u16(0x011A); u16(5); u32(1);   // tag, type=RATIONAL, count=1
    u32(0);                        // inline value: numerator=1, denominator=0 (4 bytes only!)
    // RATIONAL needs 8 bytes -> value doesn't fit; write it as offset instead
    s.clear();
    u16(0x011A); u16(5); u32(1);
    u32(20);                       // value offset
    u32(1); u32(0);                // numerator=1, denominator=0
    std::istringstream in(s, std::ios::binary);
    try {
      auto entry = TiffImage::IFD::Entry::read(in, false);
      auto v = TiffExporter::getIntVec(TiffImage::IFD(), TiffCraft::Tag::XResolution); // placeholder
    } catch (const std::exception& ex) {
      std::cout << "[4] rational: " << ex.what() << "\n";
    }
  }
  return 0;
}
