      std::cout << "[B] text.tif via Any (ifdIndex=1) threw: " << e.what() << "\n";
    }
  } else if (which == 2) {
    // truncated file: strip byte count larger than the remaining data
    // Build a synthetic TIFF: header, IFD with ImageWidth/Length/BitsPerSample/
    // SamplesPerPixel/PhotometricInterpretation/StripOffsets/StripByteCounts,
    // then only half of the promised strip bytes.
    std::string s;
    auto u16 = [&](uint16_t v){ s.append((char*)&v, 2); };
    auto u32 = [&](uint32_t v){ s.append((char*)&v, 4); };
    u16(0x4949); u16(42); u32(8);
    const uint32_t stripOffset = 8 + 2 + 12*8 + 4; // after the IFD
    const uint32_t promised = 16;
    u16(8); // entry count
    auto ent = [&](uint16_t tag, uint16_t type, uint32_t count, uint32_t val){
      u16(tag); u16(type); u32(count); u32(val);
    };
    ent(0x0100, 3, 1, 4);      // ImageWidth = 4
    ent(0x0101, 3, 1, 4);      // ImageLength = 4
    ent(0x0102, 3, 1, 8);      // BitsPerSample = 8
    ent(0x0103, 3, 1, 1);      // Compression = 1
    ent(0x0106, 3, 1, 1);      // Photometric = 1 (BlackIsZero)
    ent(0x0111, 4, 1, stripOffset); // StripOffsets
    ent(0x0115, 3, 1, 1);      // SamplesPerPixel = 1
    ent(0x0117, 4, 1, promised);   // StripByteCounts = 16
    u32(0);                   // next IFD = 0
    s.append(8, '\0');        // only 8 of the 16 promised bytes
    std::istringstream in(s, std::ios::binary);
    try {
      TiffExporterAny ex;
      load(in, std::ref(ex), LoadParams{});
      const auto& d = ex.image().data;
      size_t nonzero = 0;
      for (auto b : d) if (b != std::byte{0}) ++nonzero;
      std::cout << "[C] truncated strip: NO error thrown. dataSize=" << d.size()
                << " nonzero bytes=" << nonzero << " (promised 16, provided 8)\n";
    } catch (const std::exception& e) {
      std::cout << "[C] truncated strip: threw: " << e.what() << "\n";
    }
  }
  return 0;
}
