  labels: (i.labels || []).map(l => l.name || l),
  type: i.type, url: i.html_url,
  bodyLen: (i.body || "").length,
  checklist: ((i.body || "").match(/^- \[ \]/gm) || []).length,
  phases: ((i.body || "").match(/^## .*/gm) || []),
  tail: (i.body || "").slice(-300)
}, null, 1);

const cur = await tools.github.issue_read({ method: "get", owner: "danielm5", repo: "tiffcraft", issue_number: 22 });
const body = (cur && cur.issue) ? cur.issue.body : cur.body;

const lines = body.split("\n");
const out = [];
let converted = 0, skipped = [];
for (const line of lines) {
  // Phase 0 items are "### P0.1 <text> **[verified]**"
  let m = line.match(/^### (P\d+\.\d+) (.*)$/);
  if (m) {
    let text = m[2];
    let verified = "";
    const vm = text.match(/^(.*)\s*\*\*\[verified\]\*\*$/);
    if (vm) { text = vm[1]; verified = " **[verified]**"; }
    out.push("- [ ] **" + m[1] + " " + text + "**" + verified);
    converted++;
    continue;
  }
  // Phase 1/2/3 and testing items are "- **P1.1** ..." / "- **T1** ..."
  m = line.match(/^(- )\*\*((?:P\d+\.\d+|T\d+))\*\* (?!—)(.*)$/);
  if (m) {
    out.push("- [ ] **" + m[2] + "** " + m[3]);
    converted++;
    continue;
  }
  // Appendix evidence lines use an em dash after the id -> leave as bullets
  if (/^- \*\*(?:P\d+\.\d+|T\d+)\*\* —/.test(line)) { skipped.push(line.slice(0, 24)); }
  out.push(line);
}

const newBody = out.join("\n");
const checkboxes = (newBody.match(/^- \[ \]/gm) || []).length;
const res = await tools.github.issue_write({
  method: "update", owner: "danielm5", repo: "tiffcraft", issue_number: 22, body: newBody
});
return JSON.stringify({
  converted, appendixBulletsLeftAlone: skipped.length,
  checkboxes,
  lenBefore: body.length, lenAfter: newBody.length,
  update: JSON.stringify(res).slice(0, 200)
}, null, 1);

