#include <tiffcraft/TiffCraft.hpp>
#include <iostream>
#include <sstream>
using namespace TiffCraft;

int main() {
  // Build a RATIONAL entry: tag=XResolution, type=RATIONAL, count=1, numerator=1, denominator=0
  std::string s;
  auto u16 = [&](uint16_t v){ s.append((char*)&v, 2); };
  auto u32 = [&](uint32_t v){ s.append((char*)&v, 4); };
  u16(0x011A); u16(5); u32(1);   // tag, type=RATIONAL, count=1
  u32(20);                        // value offset
  // pad to offset 20
  while (s.size() < 20) s.push_back('\0');
  u32(1); u32(0);                // numerator=1, denominator=0
  std::istringstream in(s, std::ios::binary);
  auto entry = TiffImage::IFD::Entry::read(in, false);
  try {
    auto v = TiffExporter::makeIntVec<Rational>(entry);
    std::cout << "makeIntVec returned " << v[0] << " (should not happen)\n";
  } catch (const std::exception& e) {
    std::cout << "makeIntVec threw: " << e.what() << "\n";
  }
  return 0;
}
EOF
